          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function CheckboxOption({ questionId, option, optionIndex }) {
        const inputId = `${questionId}-option-${optionIndex + 1}`;

        return `
          <label class="choice" for="${inputId}">
            <input
              id="${inputId}"
              type="checkbox"
              name="${questionId}"
              value="${escapeHtml(option)}"
            />
