   <body>
     <a class="skip-link" href="#main-content">Skip to main content</a>
     <div id="app"></div>

     <script>
       const quizQuestions = [
         {
           id: "question-1",
           prompt: "Which of these are commonly used for front-end web development?",
           helpText: "Select every language you would expect to work with directly in a browser-based product interface.",
           options: ["HTML", "JavaScript", "CSS", "Python"],
           correctAnswers: ["HTML", "JavaScript", "CSS"]
         },
         {
           id: "question-2",
           prompt: "Which of these are statically typed programming languages?",
           options: ["Java", "TypeScript", "Ruby", "C#"],
           correctAnswers: ["Java", "TypeScript", "C#"]
         },
         {
           id: "question-3",
           prompt: "Which languages are widely used for systems programming?",
           options: ["Rust", "C", "Go", "SQL"],
           correctAnswers: ["Rust", "C", "Go"]
         }
       ];

       const appRoot = document.getElementById("app");

       function escapeHtml(value) {
         return value
           .replaceAll("&", "&amp;")
           .replaceAll("<", "&lt;")
           .replaceAll(">", "&gt;")
           .replaceAll('"', "&quot;")
           .replaceAll("'", "&#39;");
       }

       function CheckboxOption({ questionId, option, optionIndex }) {
         const inputId = `${questionId}-option-${optionIndex + 1}`;

         return `
           <label class="choice" for="${inputId}">
             <input
               id="${inputId}"
               type="checkbox"
               name="${questionId}"
               value="${escapeHtml(option)}"
             />
             <span class="choice-label">${escapeHtml(option)}</span>
           </label>
         `;
       }

       function HelpText({ id, text }) {
         return `<p class="question-help" id="${id}">${escapeHtml(text)}</p>`;
       }

       function QuestionField({ question, index }) {
         const helpTextId = `${question.id}-help`;
         const describedBy = question.helpText ? ` aria-describedby="${helpTextId}"` : "";

         return `
           <div class="form-field">
             <fieldset${describedBy}>
               <legend>${index + 1}. ${escapeHtml(question.prompt)}</legend>
               ${question.helpText ? HelpText({ id: helpTextId, text: question.helpText }) : ""}
               <div class="choices">
                 ${question.options
                   .map((option, optionIndex) =>
                     CheckboxOption({
                       questionId: question.id,
                       option,
                       optionIndex
                     })
                   )
                   .join("")}
               </div>
             </fieldset>
           </div>
         `;
       }

       function QuizForm() {
         return `
           <form id="quiz-form" novalidate>
             <div class="form-grid">
               ${quizQuestions.map((question, index) => QuestionField({ question, index })).join("")}
             </div>
             <div class="actions">
               <button type="submit">Submit answers</button>
               <div class="results" id="quiz-results" aria-live="polite">
                 Pick your answers and submit to see your score.
               </div>
             </div>
           </form>
         `;
       }

       function App() {
         return `
           <main id="main-content">
             <div class="page-shell">
               <header class="hero">
                 <div class="eyebrow">Multi-select quiz</div>
                 <h1>Computer languages quick check</h1>
                 <p class="intro">
                   Explore three short questions about programming and web languages. Each question supports multiple answers,
                   so choose every option you think applies.
                 </p>
               </header>
               <section class="quiz-card" aria-label="Quiz">
                 ${QuizForm()}
               </section>
             </div>
           </main>
         `;
       }

       function getSelections(formData, questionId) {
         return formData.getAll(questionId);
       }

       function isCorrectSelection(selected, correctAnswers) {
         if (selected.length !== correctAnswers.length) {
           return false;
         }

         const selectedSet = new Set(selected);
         return correctAnswers.every((answer) => selectedSet.has(answer));
       }

       function handleSubmit(event) {
         event.preventDefault();

         const form = event.currentTarget;
         const formData = new FormData(form);
         const results = document.getElementById("quiz-results");

         const answeredCount = quizQuestions.filter((question) => getSelections(formData, question.id).length > 0).length;
         const score = quizQuestions.filter((question) =>
           isCorrectSelection(getSelections(formData, question.id), question.correctAnswers)
         ).length;

         results.dataset.state = "filled";
         results.innerHTML = `<strong>Score:</strong> ${score} / ${quizQuestions.length}. You answered ${answeredCount} of ${quizQuestions.length} questions.`;
')
